function opPayMoney(float $amount): string { return '₱' . number_format($amount, 2); }
function opPayLabel(string $value): string {
    $value = trim(str_replace(['_', '-'], ' ', strtolower($value)));
    return match ($value) { '' => 'Not specified', 'package' => 'Tour Package', 'tourguide' => 'Tour Guide', 'qrph' => 'QR Ph', 'paymongo' => 'PayMongo', default => ucwords($value) };
}
function opPayStatusClass(string $status): string {
    return match (strtolower($status)) { 'paid', 'succeeded', 'completed' => 'paid', 'pending', 'processing' => 'pending', 'failed', 'cancelled', 'expired' => 'failed', default => '' };
}
function opPayCsvSafe(string $value): string { return preg_match('/^\s*[=+\-@]/u', $value) ? "'" . $value : $value; }
function opPaySource(array $row): string {
    $metadata = json_decode((string)($row['metadata'] ?? ''), true);
    $source = is_array($metadata) ? strtolower((string)($metadata['source'] ?? '')) : '';
    return match ($source) {
        'operator_booking_payment' => 'Collected by operator', 'tourist_profile_balance' => 'Paid by tourist',
        'booking_checkout' => 'Booking checkout', 'admin_booking_payment' => 'Collected by website admin',
        default => strtolower((string)($row['provider'] ?? '')) === 'cash' ? 'Recorded by operator' : 'Online checkout'
    };
}
function opPayChannel(array $row): string {
    return strtolower((string)($row['payment_method_type'] ?? '')) === 'cash' ? 'Cash' : opPayLabel((string)($row['provider'] ?? ''));
}
function opPayReference(array $row): string {
    return strtolower((string)($row['payment_method_type'] ?? '')) === 'cash' ? 'Cash' : (string)($row['merchant_reference'] ?? '');
}
function opPayComparison(float $current, float $previous, bool $lowerIsBetter = false): array {
    $percentage = abs($previous) < .001 ? (abs($current) < .001 ? 0.0 : 100.0) : (($current - $previous) / abs($previous)) * 100;
    if (abs($percentage) < .05) return ['label' => 'No change', 'tone' => 'neutral', 'direction' => 'flat'];
    $improved = $lowerIsBetter ? $percentage < 0 : $percentage > 0;
    return ['label' => ($percentage > 0 ? '↑ ' : '↓ ') . number_format(abs($percentage), 1) . '%', 'tone' => $improved ? 'positive' : 'attention', 'direction' => $percentage > 0 ? 'up' : 'down'];
}
function opPayTrendVisual(array $trend): string {
    $direction=(string)($trend['direction']??'flat');$tone=(string)($trend['tone']??'neutral');
    $points=match($direction){'up'=>'2,23 15,18 28,20 43,10 56,13 70,3','down'=>'2,5 15,10 28,8 43,18 56,15 70,24',default=>'2,14 15,12 28,15 43,13 56,14 70,13'};
    $tip=$direction==='up'?'M64 3h6v6':($direction==='down'?'M64 24h6v-6':'M65 10l5 3-5 3');
    $end=$direction==='up'?3:($direction==='down'?24:13);
    return '<span class="hp-stat-trend '.htmlspecialchars($tone,ENT_QUOTES).'" aria-hidden="true"><svg viewBox="0 0 72 28"><path class="guide" d="M2 25H70"/><polyline class="line" points="'.$points.'"/><circle cx="70" cy="'.$end.'" r="2.5"/><path class="arrow" d="'.$tip.'"/></svg></span>';
}
function opPayTableExists(PDO $pdo, string $table): bool {
    $stmt = $pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');
    $stmt->execute([$table]); return (int)$stmt->fetchColumn() > 0;
}

