$balanceStmt=$pdo->prepare("SELECT b.booking_id,b.booking_reference,b.booking_type,b.package_name,b.booking_date,b.grand_total,b.payment_amount,b.remaining_balance,b.status,b.phone_number,b.location,b.pax,b.num_adults,b.num_children,b.jump_off_port,b.is_complete,b.payment_method,b.created_at,COALESCE(NULLIF(TRIM(t.full_name),''),CONCAT('Tourist #',b.tourist_id)) guest_name,COALESCE(t.email,'') email FROM bookings b LEFT JOIN tourist t ON t.tourist_id=b.tourist_id WHERE b.operator_id=? AND LOWER(b.booking_type)='package' AND b.remaining_balance>0 AND LOWER(b.status) NOT IN ('cancelled','declined') ORDER BY b.booking_date,b.created_at");
