$whereSql=' WHERE '.implode(' AND ',$where);
$selectSql="SELECT pt.*,COALESCE(NULLIF(TRIM(t.full_name),''),CONCAT('Tourist #',b.tourist_id)) guest_name,COALESCE(t.email,'') email,b.package_name,b.booking_type,b.booking_date,b.grand_total booking_total,b.payment_amount booking_paid,b.remaining_balance booking_balance FROM payment_transactions pt INNER JOIN bookings b ON b.booking_id=pt.booking_id AND LOWER(b.booking_type)=LOWER(pt.booking_domain) LEFT JOIN tourist t ON t.tourist_id=b.tourist_id";
