 if(($_GET['export']??'')==='csv'){$s=$pdo->prepare($selectSql.$whereSql.' ORDER BY COALESCE(pt.paid_at,pt.created_at) DESC');$s->execute($params);$rows=$s->fetchAll(PDO::FETCH_ASSOC)?:[];header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="operator-payment-transactions-'.date('Y-m-d').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['iTour Mercedes — Operator Payment Transaction Report']);fputcsv($out,['Operator',$operatorName]);fputcsv($out,['Generated',date('F j, Y g:i A')]);fputcsv($out,[]);fputcsv($out,['Transaction Reference','Booking Reference','Guest','Email','Service','Payment Date','Channel','Method','Amount (PHP)','Status']);foreach($rows as $row)fputcsv($out,[opPayCsvSafe(opPayReference($row)),opPayCsvSafe((string)$row['booking_reference']),opPayCsvSafe((string)$row['guest_name']),opPayCsvSafe((string)$row['email']),opPayCsvSafe((string)$row['package_name']),date('Y-m-d H:i:s',strtotime((string)($row['paid_at']?:$row['created_at']))),opPayChannel($row),opPayLabel((string)$row['payment_method_type']),number_format(((int)$row['amount_minor'])/100,2,'.',''),opPayLabel((string)$row['status'])]);fclose($out);exit;}
 $s=$pdo->prepare('SELECT COUNT(*) FROM payment_transactions pt INNER JOIN bookings b ON b.booking_id=pt.booking_id AND LOWER(b.booking_type)=LOWER(pt.booking_domain) LEFT JOIN tourist t ON t.tourist_id=b.tourist_id'.$whereSql);$s->execute($params);$transactionCount=(int)$s->fetchColumn();$totalPages=max(1,(int)ceil($transactionCount/$perPage));$page=min($page,$totalPages);$offset=($page-1)*$perPage;$s=$pdo->prepare($selectSql.$whereSql.' ORDER BY COALESCE(pt.paid_at,pt.created_at) DESC,pt.payment_transaction_id DESC LIMIT '.$perPage.' OFFSET '.$offset);$s->execute($params);$transactions=$s->fetchAll(PDO::FETCH_ASSOC)?:[];
